import React, { useState, useEffect } from "react";
import axios from "axios";

function App() {
  const [ads, setAds] = useState([]);
  const [feedback, setFeedback] = useState("Click the button to simulate an ad click!");
  const [stats, setStats] = useState({});

  // Fetch the list of ads from the Flask backend
  useEffect(() => {
    axios.get("http://localhost:5000/api/ads")
      .then((response) => {
        setAds(response.data.ads);
      })
      .catch((error) => {
        console.error("Error fetching ads:", error);
      });
  }, []);

  // Fetch statistics for A/B testing
  const fetchStats = () => {
    axios.get("http://localhost:5000/api/stats")
      .then((response) => {
        setStats(response.data);
      })
      .catch((error) => {
        console.error("Error fetching stats:", error);
      });
  };

  // Handle ad click
  const handleAdClick = () => {
    axios.post("http://localhost:5000/api/click_ad")
      .then((response) => {
        const { ad_id, click, reward } = response.data;
        setFeedback(`Ad ${ad_id} clicked! Click: ${click}, Reward: ${reward.toFixed(2)}`);
        fetchStats(); // Update statistics after each click
      })
      .catch((error) => {
        console.error("Error clicking ad:", error);
      });
  };

  return (
    <div style={{ textAlign: "center", backgroundColor: "#f0f0f0", padding: "20px" }}>
      <h1>Ads Promotion with Thompson Sampling</h1>
      <button onClick={handleAdClick} style={{ padding: "10px 20px", fontSize: "16px" }}>
        Simulate Ad Click
      </button>
      <p style={{ marginTop: "20px", fontSize: "18px" }}>{feedback}</p>

      <h2>A/B Testing Statistics</h2>
      <table style={{ margin: "0 auto", borderCollapse: "collapse", width: "80%" }}>
        <thead>
          <tr>
            <th style={{ border: "1px solid #000", padding: "10px" }}>Ad ID</th>
            <th style={{ border: "1px solid #000", padding: "10px" }}>Clicks</th>
            <th style={{ border: "1px solid #000", padding: "10px" }}>Impressions</th>
            <th style={{ border: "1px solid #000", padding: "10px" }}>Total Rewards</th>
            <th style={{ border: "1px solid #000", padding: "10px" }}>Alpha</th>
            <th style={{ border: "1px solid #000", padding: "10px" }}>Beta</th>
            <th style={{ border: "1px solid #000", padding: "10px" }}>Reward Mean</th>
            <th style={{ border: "1px solid #000", padding: "10px" }}>Reward Std</th>
          </tr>
        </thead>
        <tbody>
          {ads.map((ad) => (
            <tr key={ad}>
              <td style={{ border: "1px solid #000", padding: "10px" }}>{ad + 1}</td>
              <td style={{ border: "1px solid #000", padding: "10px" }}>{stats.clicks ? stats.clicks[ad] : 0}</td>
              <td style={{ border: "1px solid #000", padding: "10px" }}>{stats.impressions ? stats.impressions[ad] : 0}</td>
              <td style={{ border: "1px solid #000", padding: "10px" }}>{stats.total_rewards ? stats.total_rewards[ad].toFixed(2) : 0}</td>
              <td style={{ border: "1px solid #000", padding: "10px" }}>{stats.alpha ? stats.alpha[ad].toFixed(2) : 0}</td>
              <td style={{ border: "1px solid #000", padding: "10px" }}>{stats.beta ? stats.beta[ad].toFixed(2) : 0}</td>
              <td style={{ border: "1px solid #000", padding: "10px" }}>{stats.reward_mean ? stats.reward_mean[ad].toFixed(2) : 0}</td>
              <td style={{ border: "1px solid #000", padding: "10px" }}>{stats.reward_std ? stats.reward_std[ad].toFixed(2) : 0}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default App;
